"""Validate base runtime plus root-qualified add-on and prepare a NEW run plan.

Extract both runtime archives into the same empty parent directory, then run:
  python3 rdf4j/result-coordinate-evidence/rebase-root-qualified-experiment.py \
      --java /path/to/compatible/bin/java --output /new/reproduction-plan

This helper executes no Java. It validates the original 126 artifact hashes and
the exact appended launcher directory, then writes a new 127-entry classpath,
reference manifest, derivative protocol, and explicit command. Original absolute
paths and metadata are preserved. The new plan describes a reproduction, not
another observation from the recorded experiment.
"""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import runpy
import shlex
import stat
import sys


EVIDENCE = "result-coordinate-evidence"
PROTOCOL = f"{EVIDENCE}/root-qualified-confirmation-protocol.json"
ADDON_MANIFEST = f"{EVIDENCE}/root-qualified-runtime-manifest.json"
CLASS_DIRECTORY = f"{EVIDENCE}/root-qualified-launcher/classes"
CLASS_FILE = "org/eclipse/rdf4j/sail/lmdb/evaluation/RootQualifiedOptionalFanoutLauncher.class"
MEASURED_MANIFEST = f"{EVIDENCE}/root-qualified-transport-comparison/classpath-manifest.json"
SCRIPT_NAMES = ("bundle-root-qualified-runtime.py", "rebase-root-qualified-experiment.py")


def canonical_json(value: object) -> bytes:
    return (json.dumps(value, indent=2, sort_keys=True) + "\n").encode("utf-8")


def member_path(repo: Path, name: str, require) -> Path:
    parts = PurePosixPath(name).parts
    require(parts and parts[0] == "rdf4j"
            and all(part not in ("", ".", "..") for part in parts),
            f"Unsafe add-on member: {name}")
    path = repo.joinpath(*parts[1:])
    require(path.resolve(strict=True).is_relative_to(repo), f"Member escapes extraction: {name}")
    return path


def validate_inputs(repo: Path, api: dict) -> dict:
    """Validate only small add-on inputs; full base validation is separate."""
    require, digest_file = api["require"], api["file_digest"]
    protocol_bytes = (repo / PROTOCOL).read_bytes()
    protocol = json.loads(protocol_bytes)
    require(protocol["modes"] == ["off", "dense", "changes", "rows"]
            and [protocol[key] for key in ("forks", "warmup", "iterations")] == [4, 5, 5]
            and protocol["actualClasspathEntries"] == 127,
            "Original confirmation protocol shape differs")
    fixed_paths = {
        "driver": f"{EVIDENCE}/run-root-qualified-coordinate-experiments.py",
        "originalDriver": f"{EVIDENCE}/run-coordinate-experiments.py",
        "launcherSource": f"{EVIDENCE}/root-qualified-launcher/src/" + CLASS_FILE[:-6] + ".java",
        "launcherClassDirectory": CLASS_DIRECTORY,
        "frozenClasspathManifest": f"{EVIDENCE}/transport-comparison/classpath-manifest.json",
        "classpathFile": f"{EVIDENCE}/root-qualified-launcher/classpath.txt",
    }
    for key, value in fixed_paths.items():
        require(protocol[key] == value, f"Unexpected original protocol path: {key}")
    for key in ("driver", "originalDriver", "launcherSource", "frozenClasspathManifest"):
        require(digest_file(repo / protocol[key]) == protocol[key + "Sha256"],
                f"Original protocol input hash differs: {key}")
    freeze_driver = repo / EVIDENCE / "freeze-experiment-classpath.py"
    require(digest_file(freeze_driver) == protocol["originalFreezeDriverSha256"],
            "Original freeze driver hash differs")
    reference = json.loads((repo / protocol["frozenClasspathManifest"]).read_bytes())
    measured = json.loads((repo / MEASURED_MANIFEST).read_bytes())
    require(len(reference) == 126 and len(measured) == 127 and measured[:-1] == reference,
            "Measured classpath prefix differs from the original 126 entries")
    require((repo / protocol["classpathFile"]).read_bytes()
            == (":".join(entry["path"] for entry in measured) + "\n").encode("utf-8"),
            "Original 127-entry classpath text differs from the measured manifest")
    class_root = repo / CLASS_DIRECTORY
    directories, files = api["regular_tree"](class_root)
    require([file.relative_to(class_root).as_posix() for file in files] == [CLASS_FILE],
            "Launcher directory must contain exactly the one measured class")
    require(all(stat.S_ISDIR(path.lstat().st_mode) for path in directories),
            "Launcher directory contains a non-directory path")
    overlay_hash = api["tree_digest"]({CLASS_FILE: digest_file(files[0])})
    require(overlay_hash == protocol["launcherClassDirectorySha256"]
            and measured[-1]["sha256"] == overlay_hash
            and measured[-1]["kind"] == "tree" and measured[-1]["files"] == 1
            and PurePosixPath(measured[-1]["path"]).as_posix().endswith("/" + CLASS_DIRECTORY),
            "Exact appended launcher artifact differs")
    require(protocol["launcherClassFiles"] == [{"path": CLASS_FILE,
            "bytes": files[0].stat().st_size, "sha256": digest_file(files[0])}],
            "Launcher class file hash/size differs")
    return {"protocol": protocol, "protocolBytes": protocol_bytes,
            "reference": reference, "measured": measured,
            "overlayHash": overlay_hash, "overlayFiles": files,
            "overlayDirectories": directories}


def validate_addon_manifest(repo: Path, api: dict) -> dict:
    require, digest_file = api["require"], api["file_digest"]
    manifest = json.loads((repo / ADDON_MANIFEST).read_bytes())
    require(manifest["format"] == 1 and manifest["appendedEntry"]["position"] == 127,
            "Unexpected add-on manifest format/order")
    for name, record in manifest["members"].items():
        path = member_path(repo, name, require)
        mode = path.lstat().st_mode
        if record["kind"] == "directory":
            require(stat.S_ISDIR(mode), f"Missing real add-on directory: {name}")
        else:
            require(stat.S_ISREG(mode) and path.stat().st_size == record["size"]
                    and digest_file(path) == record["sha256"],
                    f"Add-on file content differs: {name}")
    return manifest


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parents[1],
                        help="Merged rdf4j/ directory from the base and add-on archives")
    parser.add_argument("--java", type=Path, required=True,
                        help="Compatible local Java executable; never executed by this helper")
    parser.add_argument("--output", type=Path, required=True, help="New directory; never overwritten")
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    api = runpy.run_path(str(repo / EVIDENCE / "rebase-coordinate-classpath.py"))
    require = api["require"]
    output = args.output.parent.resolve(strict=True) / args.output.name
    require(not os.path.lexists(output), f"Refusing to replace output: {output}")
    runtime = repo / EVIDENCE / "frozen-current"
    require(not output.is_relative_to(runtime) and not output.is_relative_to(repo / CLASS_DIRECTORY),
            "The reproduction plan must be outside immutable runtime/launcher directories")
    java = args.java.resolve(strict=True)
    require(java.is_file() and os.access(java, os.X_OK), "Java must name an executable regular file")
    addon = validate_addon_manifest(repo, api)
    inputs = validate_inputs(repo, api)
    info = api["validate_runtime"](runtime)
    protocol = inputs["protocol"]
    require(info["provenance"]["source"] == protocol["source"] == addon["source"],
            "Frozen source identity differs from the confirmation")
    rebased_reference = []
    for recorded, old, artifact in zip(inputs["reference"], info["provenance"]["entries"], info["artifacts"]):
        require(recorded["path"] == old["frozen"] and recorded["sha256"] == artifact["sha256"]
                and recorded["kind"] == ("tree" if artifact["kind"] == "directory" else "file")
                and ("files" not in recorded or recorded["files"] == artifact["files"]),
                "Original base artifact order/content differs")
        rebased_reference.append(recorded | {"path": str(artifact["path"])})
    overlay = (repo / CLASS_DIRECTORY).resolve(strict=True)
    require(os.pathsep not in str(overlay) and "\n" not in str(overlay),
            "Launcher extraction path cannot be represented in a classpath")
    paths = [entry["path"] for entry in rebased_reference] + [str(overlay)]
    reference_bytes = canonical_json(rebased_reference)
    derived = copy.deepcopy(protocol)
    derived["name"] = protocol["name"] + " — rebased reproduction"
    derived["frozenClasspathManifest"] = str(output / "base-classpath-manifest.json")
    derived["frozenClasspathManifestSha256"] = hashlib.sha256(reference_bytes).hexdigest()
    derived["classpathFile"] = str(output / "classpath.txt")
    derived["jvm"]["java"] = str(java)
    derived["jvm"]["otherJvmLoadsDuringTiming"] = "Reproducer must arrange quiet serial timing"
    derived["preRunCondition"] = "Validated immutable artifacts; reproducer must arrange quiet timing"
    derived["reproduction"] = {
        "originalProtocolSha256": hashlib.sha256(inputs["protocolBytes"]).hexdigest(),
        "originalProtocol": PROTOCOL,
        "originalJava": protocol["jvm"]["java"],
        "originalCreatedAtUtc": protocol["createdAtUtc"],
        "note": "Only host paths and this derivative command/provenance are rebased. Original protocol stays byte-identical. A new run is not part of the recorded experiment.",
    }
    command = [sys.executable, str(repo / protocol["driver"]),
               "--classpath-file", str(output / "classpath.txt"),
               "--protocol-file", str(output / "protocol.json"),
               "--java", str(java), "--heap", "1024m", "--suite", "ablation",
               "--modes", "off,dense,changes,rows", "--forks", "4", "--warmup", "5",
               "--iterations", "5", "--timeout", "240", "--source", protocol["source"],
               "--cwd", str(repo), "--output", str(output / "results")]
    derived["command"] = {"argv": command, "cwd": str(repo)}
    verification = {"validated": True, "javaExecuted": False,
                    "source": protocol["source"], "baseEntries": 126, "actualEntries": 127,
                    "overlayPosition": "last", "overlayDirectorySha256": inputs["overlayHash"],
                    "originalProtocolSha256": derived["reproduction"]["originalProtocolSha256"],
                    "originalMetadataUnmodified": True,
                    "baseArchive": addon["baseArchive"]}
    # mkdir refuses every existing destination, including links. Individual files
    # are published with the base helper's atomic no-overwrite operation.
    output.mkdir()
    for name, content in {
        "classpath.txt": (os.pathsep.join(paths) + "\n").encode("utf-8"),
        "base-classpath-manifest.json": reference_bytes,
        "protocol.json": canonical_json(derived),
        "command.json": canonical_json(derived["command"]),
        "verification.json": canonical_json(verification),
    }.items():
        api["write_new"](output / name, content)
    print(f"Validated all 127 entries; wrote a new reproduction plan: {output}")
    print("No Java process has run. Explicit reproduction command (POSIX shell):")
    print(shlex.join(command))


if __name__ == "__main__":
    main()
